// Base de componentes del editor de circuitos (fisicabit).
//
// Cada componente:
//   id      único y estable (se guarda en el archivo del circuito)
//   nombre  cómo se muestra            cat   id de CATEGORIAS
//   alias   palabras extra para el buscador (texto)
//   desc    qué es, en una o dos oraciones
//   fisica  para qué práctica de física sirve (opcional)
//   datos   ficha corta: [[rótulo, valor], …]
//   hoja    enlace a la hoja de datos (opcional)
//   tk      true si está en Tinkercad Circuits
//   pref    prefijo del rótulo (R, C, D, Q, U…)    valor  valor inicial (opcional)
//   pines   [{ n, rol, … }] en orden físico. Roles:
//             vcc { v: [mín, máx] V, i: mA }   gnd
//             aout  salida analógica (hay que leerla con un pin analógico)
//             dout  salida digital hacia la placa { nivel: V del «1» si es fijo, nivel33: true si nunca pasa de 3,3 V }
//             din   entrada digital que maneja la placa { vih: V mínimo del «1» }
//             pwm   entrada que necesita PWM (servo, zumbador pasivo, compuerta)
//             io    línea de datos de ida y vuelta (1-Wire, DHT)
//             sda scl · sck miso mosi cs
//             carga { i: mA }  terminal de potencia (motor, lámpara, bobina)
//             led { vf: V, i: mA }  pata de un LED     fuente+ { v }  fuente-     pas  pasivo
//   esq     cómo se dibuja en el esquemático:
//             { f: 'nativo', t }            uno de los símbolos que ya tiene el editor
//                                           (pol: true en un capacitor = con polaridad: placa curva del negativo y signo +)
//             { f: <símbolo de 2 patas> }   inductor · zener · fotodiodo · fusible · altavoz · solar · generador · osciloscopio · ohmimetro · rele-bobina · cristal · varistor
//             { f: <símbolo de 3 patas> }   npn · pnp · nmos · pmos · pot3 · conmutador · opamp · regulador
//             { f: 'bloque', txt, izq: [nombres de pin], der: [nombres de pin] }   caja con pines a los lados
//   proto   cómo se dibuja en la protoboard (null = no va en la protoboard):
//             { f: 'nativo', t }
//             { f: 'axial', banda?: true, txt? }        2 patas, cuerpo alargado (diodo, inductor, fusible)
//             { f: 'radial', r?, marca?, pol? }         2 patas, cuerpo redondo visto de arriba
//             { f: 'to92', marca }                      3 patas juntas, cuerpo en D
//             { f: 'to220', marca }                     3 patas juntas, cuerpo con aleta
//             { f: 'dip', txt }                         integrado a caballo del canal (patas = pines.length)
//             { f: 'modulo', txt, w?, h? }              plaqueta con tira de pines enchufada en la placa
//             { f: 'libre', txt, w?, h?, arte? }        suelto, con un borne por pin (arte: dibujo propio opcional)
//             { f: 'nativo', t: 'cubeta', forma }       cubeta con agua vista de arriba; forma de los electrodos:
//                                                       placas · cilindros · placa-cilindro · coaxial
//   esq.pines / proto.pines (opcional): nombre de pin de cada terminal físico de esa vista, cuando no
//             coinciden uno a uno con `pines` (pueden repetirse: terminales unidos por dentro, como
//             las 4 patas de un pulsador; o ser un subconjunto, como el símbolo de un operacional)
//   avisos  textos fijos para la ficha (opcional)   solo  'v2' si necesita esa versión de micro:bit
//   parte   id del sensor en la extensión FisicaBit de MakeCode (pxtparts.json de pxt-fisicabit-usb): en la protoboard
//           realista se dibuja con el mismo dibujo que usa el simulador de MakeCode y la ficha muestra su conexión y
//           sus bloques. Las patas tienen que llamarse y ordenarse como en ese dibujo. Los sensores de la extensión
//           que no estén en esta base se agregan solos (ver partes.js).
//   mb      pin de la micro:bit que representa (3V, GND, P0…): un borne suelto de la placa, sin dibujarla entera.
//           El pin se puede cambiar en cada elemento; para los avisos cuenta como ese pin de la micro:bit.

export const CATEGORIAS = [
  { id: 'basicos', nombre: 'Básicos' },
  { id: 'fuentes', nombre: 'Alimentación' },
  { id: 'entradas', nombre: 'Pulsadores y controles' },
  { id: 'sensores', nombre: 'Sensores' },
  { id: 'salidas', nombre: 'Luz, sonido y movimiento' },
  { id: 'semis', nombre: 'Diodos y transistores' },
  { id: 'integrados', nombre: 'Integrados' },
  { id: 'placas', nombre: 'Placas' },
  { id: 'instrumentos', nombre: 'Instrumentos' },
  { id: 'campo', nombre: 'Campo eléctrico' },
];

const P2 = (a, b, ra = 'pas', rb = 'pas') => [{ n: a, rol: ra }, { n: b, rol: rb }];
const nat = (t, extra) => Object.assign({ f: 'nativo', t }, extra || {});
const blo = (txt, izq, der) => ({ f: 'bloque', txt, izq, der });
const mod = (txt, w, h) => ({ f: 'modulo', txt, w, h });
const lib = (txt, w, h, arte) => ({ f: 'libre', txt, w, h, arte });
const vcc = (lo, hi, i, n = 'VCC') => ({ n, rol: 'vcc', v: [lo, hi], i });
const gnd = (n = 'GND') => ({ n, rol: 'gnd' });
const s = (n, rol, extra) => Object.assign({ n, rol }, extra || {});
const pas = (...ns) => ns.map((n) => ({ n, rol: 'pas' }));
const carga = (i, a = '1', b = '2') => [{ n: a, rol: 'carga', i }, { n: b, rol: 'carga', i }];
const CUBETA = [{ n: '−', rol: 'pas' }, { n: '+', rol: 'pas' }, { n: 'PUNTA', rol: 'aout', nivel33: true }];
const AVISO_CUBETA = ['La punta de prueba se lee con un pin analógico: MAPEO usa P1.', 'En el editor va en la pestaña del montaje, con la opción «Sin protoboard».'];
const fuente = (v, a = '+', b = '−') => [{ n: a, rol: 'fuente+', v }, { n: b, rol: 'fuente-' }];
const TI = 'https://www.ti.com/lit/ds/symlink/', VI = 'https://www.vishay.com/docs/', SF = 'https://cdn.sparkfun.com/datasheets/', ON = 'https://www.onsemi.com/pdf/datasheet/';
// Compuertas de 14 patas (74HC00, 08, 32, 86): 1A 1B 1Y 2A 2B 2Y GND 3Y 3A 3B 4Y 4A 4B VCC
const P14 = ['1A', '1B', '1Y', '2A', '2B', '2Y', 'GND', '3Y', '3A', '3B', '4Y', '4A', '4B', 'VCC'];
const logica = (ns) => ns.map((n) => (n === 'GND' ? gnd() : n === 'VCC' ? vcc(2, 6, 1) : /Y$|^Q/.test(n) ? s(n, 'dout') : s(n, 'din')));
const compuerta = (id, nombre, fn, ns, hoja) => ({ id, nombre, cat: 'integrados', alias: 'compuerta logica digital ' + fn, tk: true, pref: 'U',
  desc: 'Integrado con compuertas ' + fn + '. Trabaja de 2 a 6 V, así que se puede usar con los 3,3 V de la micro:bit.', fisica: 'Lógica digital: tablas de verdad con pulsadores y LED.',
  datos: [['Alimentación', '2–6 V'], ['Encapsulado', 'DIP-14']], hoja, pines: logica(ns), esq: blo(id.toUpperCase(), ns.slice(0, 7), ns.slice(7).reverse()), proto: { f: 'dip', txt: id.toUpperCase() } });

